retained_critical_bodies.faction_demand.0103:
faction_demand.0103 = {
	type = letter_event
	sender = scope:faction_target
	opening = {
		desc = "FACTION_DEMAND_LIBERTY_REFUSED"
	}
	desc = "FACTION_DEMAND_LIBERTY_REFUSED_DESC"

	option = {
		name = "FACTION_DEMAND_REFUSED_OPT"
		scope:faction = {
			faction_start_war = {}
			
			every_faction_member = {
				limit = { this != scope:faction.faction_leader }
				trigger_event = faction_demand.0104
			}
		}
	}
}

retained_critical_bodies.pam_evangelize_personal_tenet_decline_ef:
pam_evangelize_personal_tenet_decline_effect = {
	change_spiritual_fulfillment = miniscule_spiritual_fulfillment_loss
	if = {
		limit = {
			faith.main_rite = {
				has_tenet_status = {
					tenet = scope:pam_evangelize_tenet
					status = prohibited
				}
			}
		}
		every_secret = {
			type = secret_forbidden_personal_tenet
			limit = { NOT = { is_known_by = scope:recipient } }
			reveal_to = scope:recipient
		}
	}
}

retained_critical_bodies.pam_replace_personal_tenet_effect:
pam_replace_personal_tenet_effect = {
	save_temporary_scope_as = tenet_char
	if = {
		limit = {
			free_personal_tenet_slots = 0
		}
		random_personal_tenet = {
			weight = {
				base = 10
				modifier = {
					add = pam_tenet_popularity_impact_value
				}
			}
			scope:tenet_char = {
				remove_personal_tenet = prev
			}
		}
	}
	set_personal_tenet = $TENET$
}
